/* Halcyon Threshold Styles */

:root {
    --primary: #2563eb;
    --primary-dark: #1e40af;
    --secondary: #64748b;
    --accent: #f59e0b;
    --text: #1e293b;
    --text-light: #475569;
    --bg: #ffffff;
    --bg-alt: #f8fafc;
    --border: #e2e8f0;
    --success: #10b981;
    --warning: #f59e0b;
    --danger: #ef4444;
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
    line-height: 1.7;
    color: var(--text);
    background: var(--bg);
}

.container {
    max-width: 1100px;
    margin: 0 auto;
    padding: 0 2rem;
}

/* Header */
header {
    background: linear-gradient(135deg, var(--primary) 0%, var(--primary-dark) 100%);
    color: white;
    padding: 3rem 0 2rem;
    text-align: center;
    box-shadow: 0 2px 8px rgba(0,0,0,0.1);
}

header h1 {
    font-size: 2.5rem;
    margin-bottom: 0.5rem;
    font-weight: 700;
}

header .tagline {
    font-size: 1.1rem;
    opacity: 0.95;
    font-weight: 300;
}

/* Main Content */
main {
    padding: 3rem 0;
}

section {
    margin-bottom: 4rem;
}

h2 {
    font-size: 2rem;
    margin-bottom: 1.5rem;
    color: var(--text);
    font-weight: 700;
}

h3 {
    font-size: 1.4rem;
    margin-bottom: 1rem;
    color: var(--text);
    font-weight: 600;
}

p {
    margin-bottom: 1rem;
    color: var(--text-light);
}

a {
    color: var(--primary);
    text-decoration: none;
}

a:hover {
    text-decoration: underline;
}

/* Hero Section */
.hero {
    text-align: center;
    padding: 3rem 0;
    background: var(--bg-alt);
    border-radius: 12px;
    margin-bottom: 4rem;
}

.hero h2 {
    font-size: 2.5rem;
    line-height: 1.3;
    margin-bottom: 1.5rem;
}

.lead {
    font-size: 1.25rem;
    max-width: 800px;
    margin: 0 auto 2rem;
    line-height: 1.8;
}

.cta {
    display: flex;
    gap: 1rem;
    justify-content: center;
    flex-wrap: wrap;
}

/* Buttons */
.button {
    display: inline-block;
    padding: 0.875rem 2rem;
    border-radius: 6px;
    font-weight: 600;
    font-size: 1rem;
    transition: all 0.2s;
    text-decoration: none;
}

.button.primary {
    background: var(--primary);
    color: white;
}

.button.primary:hover {
    background: var(--primary-dark);
    transform: translateY(-2px);
    box-shadow: 0 4px 12px rgba(37, 99, 235, 0.3);
    text-decoration: none;
}

.button.secondary {
    background: white;
    color: var(--primary);
    border: 2px solid var(--primary);
}

.button.secondary:hover {
    background: var(--primary);
    color: white;
    text-decoration: none;
}

/* Cards */
.cards {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: 2rem;
    margin-top: 2rem;
}

.card {
    background: var(--bg-alt);
    padding: 2rem;
    border-radius: 8px;
    border: 1px solid var(--border);
    transition: all 0.3s;
}

.card:hover {
    transform: translateY(-4px);
    box-shadow: 0 8px 24px rgba(0,0,0,0.1);
}

.card h3 {
    margin-bottom: 1rem;
    font-size: 1.3rem;
}

/* Framework List */
.framework-list {
    list-style: none;
    margin: 2rem 0;
}

.framework-list li {
    padding: 1rem;
    margin-bottom: 0.75rem;
    background: var(--bg-alt);
    border-left: 4px solid var(--primary);
    border-radius: 4px;
}

/* Principles */
.principles {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: 1.5rem;
    margin-top: 2rem;
}

.principle {
    padding: 1.5rem;
    background: white;
    border: 2px solid var(--border);
    border-radius: 8px;
}

.principle h3 {
    color: var(--primary);
    margin-bottom: 0.75rem;
    font-size: 1.2rem;
}

/* Involvement Options */
.involvement {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
    gap: 2rem;
    margin-top: 2rem;
}

.involvement-option {
    padding: 1.5rem;
    background: var(--bg-alt);
    border-radius: 8px;
}

.involvement-option h3 {
    margin-bottom: 1rem;
    font-size: 1.3rem;
}

/* Updates */
.update {
    padding: 1.5rem;
    background: var(--bg-alt);
    border-left: 4px solid var(--success);
    border-radius: 4px;
    margin-bottom: 1rem;
}

.update-date {
    font-weight: 600;
    color: var(--primary);
    margin-bottom: 0.5rem;
}

/* Footer */
footer {
    background: var(--text);
    color: white;
    padding: 3rem 0;
    margin-top: 4rem;
    text-align: center;
}

footer p {
    color: rgba(255,255,255,0.8);
    margin-bottom: 0.5rem;
}

footer a {
    color: white;
    font-weight: 600;
}

footer a:hover {
    color: var(--accent);
}

.footer-note {
    margin-top: 2rem;
    font-style: italic;
    font-size: 0.9rem;
}

/* Framework Page Specific Styles */
.framework-content {
    max-width: 800px;
    margin: 0 auto;
}

.framework-content h2 {
    margin-top: 3rem;
    padding-top: 2rem;
    border-top: 2px solid var(--border);
}

.framework-content h2:first-of-type {
    margin-top: 0;
    border-top: none;
    padding-top: 0;
}

.framework-content h3 {
    margin-top: 2rem;
    color: var(--primary);
}

.framework-content ul, .framework-content ol {
    margin-left: 2rem;
    margin-bottom: 1.5rem;
}

.framework-content li {
    margin-bottom: 0.5rem;
    color: var(--text-light);
}

.framework-content strong {
    color: var(--text);
    font-weight: 600;
}

.framework-content blockquote {
    border-left: 4px solid var(--accent);
    padding-left: 1.5rem;
    margin: 2rem 0;
    font-style: italic;
    color: var(--text-light);
}

.framework-content hr {
    margin: 3rem 0;
    border: none;
    border-top: 2px solid var(--border);
}

.nav-back {
    margin-bottom: 2rem;
}

.meta {
    font-size: 0.9rem;
    color: var(--text-light);
    font-style: italic;
    margin-bottom: 2rem;
}

.license {
    background: var(--bg-alt);
    padding: 1.5rem;
    border-radius: 8px;
    margin-top: 3rem;
    font-size: 0.9rem;
}

/* Responsive */
@media (max-width: 768px) {
    header h1 {
        font-size: 2rem;
    }

    .hero h2 {
        font-size: 1.8rem;
    }

    .lead {
        font-size: 1.1rem;
    }

    .cta {
        flex-direction: column;
        align-items: stretch;
    }

    .cards, .principles, .involvement {
        grid-template-columns: 1fr;
    }
}

